//Pay attention to the package when compiling and running the example
package education;
import education.StudentMangement.Student;

public class ProtoTeser {
    public static void main(String...args){
        //Create an object. All the setters are generated by the protobuf compiler
        Student student = Student.newBuilder()
                .setId(101)
                .setLname("Bendada")
                .setFname("Foued")
                .setGender("M")
                .setBirthday("1/1/2001")
                .setAddress("Annaba")
                .build();

        // Serialize data to protobuf binary format
        byte[] binaryData = student.toByteArray();
        
        System.out.println("Encoded size: " + binaryData.length + " bytes");

        // Deserialize from the binary format
        try {
            Student decodedStudent = Student.parseFrom(binaryData);

            System.out.println("--- Decoded Student ---");
            System.out.println("ID: " + decodedStudent.getId());
            System.out.println("Last name: " + decodedStudent.getFname());
            System.out.println("First name: " + decodedStudent.getLname());
            System.out.println("Gender: " + decodedStudent.getGender());
            System.out.println("Birthday: " + decodedStudent.getBirthday());
            System.out.println("Address: " + decodedStudent.getAddress());

        } catch (Exception e) {
            e.printStackTrace();
        }
    }
}
